import assert from "node:assert/strict";
import test from "node:test";
import { assertOfficialTicketEvidence, collectOfficialTickets, OPENING_NIGHTS_LISTING_URL } from "../lib/collection/official-tickets";
import { assertCollectorUrl, stableHash } from "../lib/collection/http";
import type { NormalizedMilestone, NormalizedOccurrence, NormalizedOpportunity } from "../lib/collection/types";

// Every body here is synthetic. Real private captures are generated by probe-official-tickets.ts.
const origin = "https://www.openingnights.fsu.edu";
const show = `${origin}/show-details/synthetic-show`;
const target = "https://tickets.openingnights.fsu.edu/main/seats/1234";
const now = () => new Date("2026-10-21T20:00:00Z");
const page = (body: string) => `<!doctype html><html><body><main>${body}</main></body></html>`;
const card = (slug = "synthetic-show", date = "Feb 4, 2027", button = "") => `<div class="highlight-card"><a class="highlight-card-link" href="${origin}/show-details/${slug}"><h3 class="highlight-title-line">Synthetic Show</h3><div class="highlight-date-line">${date}</div><span class="highlight-tag">Theatre</span></a><div class="highlight-card-actions">${button}</div></div>`;
const detail = (action = `Tickets go on sale Nov 30, 2026 at 11:00 AM`, disabled = true, href = target, extra = "") => page(`<div class="dr-show-hero-copy"><h1>Synthetic Show</h1></div><div class="dr-show-hero-actions">${action ? `<a class="dr-show-action ${disabled ? "disabled" : ""}" href="${href}">${action}</a>` : ""}</div>${extra}`);
const collect = (listing = page(card()), body = detail()) => {
  const requests: string[] = [];
  const fetcher = (async (input: URL | RequestInfo) => {
    requests.push(String(input));
    return new Response(String(input) === OPENING_NIGHTS_LISTING_URL ? listing : body, { headers: { "content-type": "text/html" } });
  }) as typeof fetch;
  return collectOfficialTickets({ now, fetch: fetcher }).then(batch => ({ batch, requests }));
};

test("official ticket routes allow only exact listing and bounded same-host show slugs", () => {
  assert.equal(assertCollectorUrl(OPENING_NIGHTS_LISTING_URL).pathname, "/events");
  assert.equal(assertCollectorUrl(show).pathname, "/show-details/synthetic-show");
  for (const url of ["http://www.openingnights.fsu.edu/events", `${origin}/show-details/../admin`, `${origin}/show-details/foo/bar`, `${origin}/show-details/foo?secret=yes`, `${origin}/show-details/foo#fragment`, `${origin}/show-details/foo%2fbar`, "https://www.openingnights.fsu.edu.evil.test/events", "https://tickets.openingnights.fsu.edu/main/seats/1234"]) assert.throws(() => assertCollectorUrl(url));
});

test("explicit official release local date remains distinct from performance and unknown timezone", async () => {
  const { batch, requests } = await collect();
  assert.equal(batch.status, "success"); assert.deepEqual(requests, [OPENING_NIGHTS_LISTING_URL, show]);
  assert.equal(batch.opportunities.length, 1); assert.equal(batch.occurrences[0].startDate, "2027-02-04");
  assert.equal(batch.occurrences[0].startAt, null); assert.equal(batch.occurrences[0].endAt, null); assert.equal(batch.occurrences[0].timezone, null); assert.equal(batch.occurrences[0].lifecycle, "unknown");
  const release = batch.milestones!.find(row => row.kind === "ticket_release")!;
  assert.equal(release.occursOn, "2026-11-30"); assert.equal(release.occursAt, null); assert.equal(release.timezone, null); assert.equal(release.sourceLocalText, "Tickets go on sale Nov 30, 2026 at 11:00 AM");
  assert.equal(release.actionUrl, target); assert.equal(batch.observations.requests, 2);
  for (const item of [...batch.opportunities, ...batch.occurrences, ...batch.milestones!]) assert.doesNotThrow(() => assertOfficialTicketEvidence(batch.sourceId, item, batch.pages.find(page => page.nativeId === item.captureNativeId)!));
});

test("sale-to-link change revises stable notice identity without claiming inventory or first release", async () => {
  const first = (await collect()).batch;
  const second = (await collect(page(card("synthetic-show", "Feb 4, 2027", `<a href="${target}">Buy Tickets</a>`)), detail("GET TICKETS", false))).batch;
  const oldLink = first.milestones![0], newLink = second.milestones![0];
  assert.equal(second.status, "success"); assert.equal(oldLink.nativeId, newLink.nativeId); assert.notEqual(oldLink.contentSha256, newLink.contentSha256);
  assert.equal(newLink.availability, "link_observed"); assert.equal(newLink.occursOn, null); assert.equal(newLink.occursAt, null);
  assert.match(newLink.uncertainty!, /not the true first release/);
  assert.equal(first.occurrences[0].contentSha256, second.occurrences[0].contentSha256);
});

test("one current notice reconciles release to link to missing to corrected release without stale date rows", async () => {
  const bodies = [detail(), detail("GET TICKETS", false), detail(""), detail("Tickets go on sale Dec 2, 2026 at 10:00 AM")];
  const notices = [];
  for (const body of bodies) {
    const batch = (await collect(page(card()), body)).batch;
    assert.equal(batch.status, "success"); assert.equal(batch.milestones!.length, 1);
    const notice = batch.milestones![0]; notices.push(notice);
    assert.equal(notice.nativeId, `${show}#ticket-notice`);
    assert.equal(notice.evidencePointer, "official-ticket:synthetic-show:ticket-notice");
    assert.doesNotThrow(() => assertOfficialTicketEvidence(batch.sourceId, notice, batch.pages[1]));
  }
  assert.deepEqual(notices.map(row => row.kind), ["ticket_release", "ticket_link", "ticket_link", "ticket_release"]);
  assert.deepEqual(notices.map(row => row.occursOn), ["2026-11-30", null, null, "2026-12-02"]);
  assert.deepEqual(notices.map(row => row.availability), ["announced_release", "link_observed", "unknown", "announced_release"]);
  assert.equal(notices[2].actionUrl, null); assert.equal(notices[2].sourceLocalText, null);
  assert.match(notices[2].uncertainty!, /no longer a current verified claim/);
  assert.equal(new Set(notices.map(row => row.contentSha256)).size, 4);
});

test("absent link is a stable unknown observation, not sold out or a cancellation", async () => {
  const result = (await collect(page(card()), detail(""))).batch;
  assert.equal(result.status, "success"); assert.equal(result.milestones!.length, 1);
  assert.equal(result.milestones![0].availability, "unknown"); assert.equal(result.milestones![0].actionUrl, null);
  assert.equal(result.occurrences[0].lifecycle, "unknown");
});

test("structured performance-time offer metadata never becomes a release milestone", async () => {
  const metadata = '<script type="application/ld+json">{"offers":{"availability":"InStock","availabilityStarts":"2027-02-04 19:30:00","validFrom":"2027-02-04 19:30:00"}}</script>';
  const result = (await collect(page(card()), detail("", true, target, metadata))).batch;
  assert.equal(result.status, "success"); assert.equal(result.milestones!.length, 1);
  assert.equal(result.milestones![0].occursOn, null); assert.equal(result.milestones![0].availability, "unknown");
});

test("date edit keeps show and occurrence identities; program range remains text without guessed end", async () => {
  const first = (await collect()).batch, second = (await collect(page(card("synthetic-show", "Mar 4 - Mar 6, 2027")))).batch;
  assert.equal(second.status, "success"); assert.equal(first.occurrences[0].nativeId, second.occurrences[0].nativeId);
  assert.notEqual(first.occurrences[0].contentSha256, second.occurrences[0].contentSha256); assert.equal(second.occurrences[0].endAt, null);
  assert.match(second.opportunities[0].uncertainties.join(" "), /individual sessions/);
});

test("off-host detail and ticket hrefs are never fetched", async () => {
  const first = await collect(page(card().replace(show, "https://attacker.invalid/detail")));
  assert.equal(first.batch.status, "partial"); assert.equal(first.requests.length, 1);
  const second = await collect(page(card()), detail("GET TICKETS", false, "https://attacker.invalid/cart"));
  assert.equal(second.batch.status, "partial"); assert.equal(second.requests.length, 2);
});

test("login wall, dynamic shell, truncated HTML, duplicate identities and pagination never succeed empty", async () => {
  for (const body of [page("Please sign in to continue"), page("{:SearchDate}"), page(card()).replace("</html>", ""), page(card() + card()), page(card() + '<a rel="next" href="?page=2">Next</a>'), page("")]) {
    const { batch, requests } = await collect(body);
    assert.notEqual(batch.status, "success"); assert.equal(batch.cursor, null); assert.equal(batch.observations.paginationComplete, false); assert.equal(requests.length, 1);
    assert.ok(batch.reason);
  }
});

test("card/details mismatch and contradictory targets remain incomplete", async () => {
  for (const body of [detail().replace("<h1>Synthetic Show</h1>", "<h1>Different Show</h1>"), detail("GET TICKETS", false, target.replace("1234", "5678"))]) {
    const listing = body.includes("5678") ? page(card("synthetic-show", "Feb 4, 2027", `<a href="${target}">Buy Tickets</a>`)) : page(card());
    const { batch } = await collect(listing, body);
    assert.equal(batch.status, "partial"); assert.equal(batch.cursor, null);
  }
});

test("unsupported soldout text, yearless release and malformed clocks fail closed", async () => {
  for (const action of ["SOLD OUT", "Tickets go on sale Nov 30 at 11:00 AM", "Tickets go on sale Nov 30, 2026 at 24:00 AM", "Tickets go on sale Feb 30, 2026 at 11:00 AM"]) {
    const { batch } = await collect(page(card()), detail(action));
    assert.equal(batch.status, "partial"); assert.equal(batch.cursor, null); assert.equal(batch.milestones!.length, 0);
  }
});

test("page bound stops before detail requests and rate limit retains retry floor", async () => {
  let requests = 0;
  const batch = await collectOfficialTickets({ now, maxPages: 2, fetch: (async () => { requests++; return new Response(page(card() + card("synthetic-two"))); }) as typeof fetch });
  assert.equal(batch.status, "partial"); assert.equal(requests, 1);
  const limited = await collectOfficialTickets({ now, fetch: (async () => new Response(null, { status: 429, headers: { "retry-after": "120" } })) as typeof fetch });
  assert.equal(limited.status, "rate_limited"); assert.equal(limited.retryAfterSeconds, 120); assert.equal(limited.observations.requests, 1); assert.equal(limited.cursor, null);
});

test("native evidence pointers cannot cross captures, source identities or notice types", async () => {
  const { batch } = await collect(), item = batch.milestones![0], capture = batch.pages[1];
  assert.throws(() => assertOfficialTicketEvidence("fsu-calendar-api", item, capture));
  assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, { ...item, nativeId: "forged" }, capture));
  assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, item, batch.pages[0]));
  const noRelease = { ...capture, body: detail("GET TICKETS", false) };
  assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, item, noRelease));
});

test("captured source facts reject forged semantic fields even with a recomputed content hash", async () => {
  const { batch } = await collect();
  type Item = NormalizedOpportunity | NormalizedOccurrence | NormalizedMilestone;
  const mutations: Array<[Item, string, unknown]> = [
    ...Object.entries({ title: "Forged title", description: "Forged description", sourceUrl: "https://attacker.invalid/", kind: "program", campusRelation: "campus", categories: ["invented"], sourcePublishedAt: "2026-10-01T00:00:00Z", uncertainties: [] }).map(([key, value]) => [batch.opportunities[0], key, value] as [Item, string, unknown]),
    ...Object.entries({ startDate: "2027-02-05", startAt: "2027-02-04T19:30:00Z", datePrecision: "instant", timezone: "America/New_York", location: "Invented venue", allDay: true, lifecycle: "scheduled", sourceLocalText: "Feb 5, 2027" }).map(([key, value]) => [batch.occurrences[0], key, value] as [Item, string, unknown]),
    ...Object.entries({ kind: "ticket_link", occursOn: "2026-12-01", occursAt: "2026-11-30T16:00:00Z", timezone: "America/New_York", sourceLocalText: "Tickets are on sale now", availability: "InStock", actionUrl: "https://tickets.openingnights.fsu.edu/main/seats/9999", uncertainty: "", occurrenceNativeId: "invented" }).map(([key, value]) => [batch.milestones![0], key, value] as [Item, string, unknown]),
  ];
  for (const [original, key, value] of mutations) {
    const forged = { ...original, [key]: value };
    const { contentSha256: _hash, captureNativeId: _capture, evidencePointer: _pointer, ...facts } = forged;
    forged.contentSha256 = stableHash(facts);
    assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, forged, batch.pages.find(page => page.nativeId === original.captureNativeId)!), `Forged ${key} must fail even with a matching forged hash`);
  }
});

test("alternate evidence prefixes and capture metadata cannot bypass source reconstruction", async () => {
  const { batch } = await collect();
  for (const item of [...batch.opportunities, ...batch.occurrences, ...batch.milestones!]) {
    const capture = batch.pages.find(page => page.nativeId === item.captureNativeId)!;
    for (const pointer of ["/events/0", "official-deadline:cre:123", "official-ticket:other-show:ticket-notice", "official-ticket:synthetic-show:ticket-release"]) assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, { ...item, evidencePointer: pointer }, capture));
    assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, { ...item, captureNativeId: "other-capture" }, capture));
    assert.throws(() => assertOfficialTicketEvidence(batch.sourceId, { ...item, contentSha256: "0".repeat(64) }, capture));
  }
});

test("real elapsed budget bounds slow details despite a frozen source clock", async t => {
  let elapsed = 0, requests = 0;
  t.mock.method(Date, "now", () => elapsed);
  const result = await collectOfficialTickets({ now, fetch: (async input => {
    requests++; elapsed += 30_000;
    return new Response(String(input) === OPENING_NIGHTS_LISTING_URL ? page(card() + card("synthetic-two")) : detail(), { headers: { "content-type": "text/html" } });
  }) as typeof fetch });
  assert.equal(result.status, "partial"); assert.equal(requests, 3); assert.equal(result.observations.requests, 3);
  assert.match(result.reason!, /75-second collection wall-time budget/);
  assert.equal(result.pages.length, 3); assert.equal(result.milestones!.length, 1);
  assert.equal(result.cursor, null); assert.equal(result.observations.paginationComplete, false);
});

test("elapsed budget is checked before issuing another detail request", async t => {
  let calls = 0, requests = 0;
  t.mock.method(Date, "now", () => ++calls <= 3 ? 0 : 76_000);
  const result = await collectOfficialTickets({ now, fetch: (async () => { requests++; return new Response(page(card())); }) as typeof fetch });
  assert.equal(result.status, "partial"); assert.equal(requests, 1);
  assert.match(result.reason!, /before another request/); assert.equal(result.cursor, null);
});
